import type Core from 'handsontable/core';

export interface TreeRowMeta {
  row: number;
  col: number;
  children?: number[];
  showLevel?: number;
  treeParent?: number | null;
  treeLevel?: number;
  cellType?: string;
  treeConfig?: { showLevel?: number } | null;
}

export interface TreeNode extends TreeRowMeta {
  key: string;
  children: number[];
  parentKey: string | null;
}

export interface TreeIndex {
  nodes: Map<string, TreeNode>;
  roots: string[];
}

interface TreeCollapseState {
  index: TreeIndex;
  collapsedNodeKeys: Set<string>;
  hiddenRows: Set<number>;
}

const treeStateByHot = new WeakMap<Core, TreeCollapseState>();

export function getTreeNodeKey(row: number, col: number) {
  return `${col}:${row}`;
}

function normalizeNumber(value: unknown): number | null {
  if (value === null || value === undefined || value === '') return null;
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : null;
}

function normalizeShowLevel(value: unknown) {
  const showLevel = normalizeNumber(value);
  return showLevel === null ? 1 : Math.max(1, Math.floor(showLevel));
}

function mergeTreeRows(treeRows: TreeRowMeta[] = [], cells: TreeRowMeta[] = []) {
  const rows = new Map<string, TreeRowMeta>();
  const configuredRows = Array.isArray(treeRows) ? treeRows : [];
  const configuredKeys = new Set<string>();

  configuredRows.forEach((tree) => {
    const row = normalizeNumber(tree?.row);
    const col = normalizeNumber(tree?.col);
    if (row !== null && col !== null) configuredKeys.add(getTreeNodeKey(row, col));
  });

  function mergeRow(tree: TreeRowMeta, fallback: boolean) {
    const row = normalizeNumber(tree?.row);
    const col = normalizeNumber(tree?.col);
    if (row === null || col === null) return;

    const key = getTreeNodeKey(row, col);
    const existing = rows.get(key);
    const showLevel = normalizeNumber(tree?.showLevel ?? tree?.treeConfig?.showLevel);
    const treeLevel = normalizeNumber(tree?.treeLevel);

    rows.set(key, {
      ...existing,
      ...tree,
      row,
      col,
      children: Array.isArray(tree?.children) ? tree.children : existing?.children,
      showLevel:
        showLevel ??
        existing?.showLevel ??
        (fallback && !configuredKeys.has(key) ? Number.MAX_SAFE_INTEGER : undefined),
      treeLevel: treeLevel ?? existing?.treeLevel
    });
  }

  (Array.isArray(cells) ? cells : [])
    .filter((cell) => cell?.cellType === 'tree')
    .forEach((cell) => mergeRow(cell, true));
  configuredRows.forEach((tree) => mergeRow(tree, false));

  return Array.from(rows.values());
}

export function buildTreeIndex(treeRows: TreeRowMeta[] = []): TreeIndex {
  const nodes = new Map<string, TreeNode>();

  treeRows.forEach((tree) => {
    const row = normalizeNumber(tree?.row);
    const col = normalizeNumber(tree?.col);
    if (row === null || col === null) return;

    const children = Array.from(
      new Set(
        (Array.isArray(tree.children) ? tree.children : [])
          .map(normalizeNumber)
          .filter((child): child is number => child !== null && child !== row)
      )
    );
    const key = getTreeNodeKey(row, col);

    nodes.set(key, {
      ...tree,
      row,
      col,
      key,
      children,
      showLevel: normalizeShowLevel(tree.showLevel),
      parentKey: null
    });
  });

  const inferredParents = new Map<string, string>();
  nodes.forEach((node) => {
    node.children.forEach((childRow) => {
      const childKey = getTreeNodeKey(childRow, node.col);
      if (nodes.has(childKey) && !inferredParents.has(childKey)) {
        inferredParents.set(childKey, node.key);
      }
    });
  });

  nodes.forEach((node) => {
    const parentRow = normalizeNumber(node.treeParent);
    const explicitParentKey = parentRow === null ? null : getTreeNodeKey(parentRow, node.col);
    node.parentKey =
      explicitParentKey && nodes.has(explicitParentKey) ? explicitParentKey : (inferredParents.get(node.key) ?? null);
  });

  const nodesByColumn = new Map<number, TreeNode[]>();
  nodes.forEach((node) => {
    const columnNodes = nodesByColumn.get(node.col) ?? [];
    columnNodes.push(node);
    nodesByColumn.set(node.col, columnNodes);
  });

  nodesByColumn.forEach((columnNodes) => {
    const ancestors: Array<{ node: TreeNode; level: number }> = [];
    columnNodes
      .sort((left, right) => left.row - right.row)
      .forEach((node) => {
        const treeLevel = normalizeNumber(node.treeLevel);
        if (treeLevel === null) return;

        while (ancestors.length && ancestors[ancestors.length - 1].level >= treeLevel) {
          ancestors.pop();
        }

        const parent = ancestors[ancestors.length - 1]?.node;
        if (!node.parentKey && treeLevel > 1 && parent) node.parentKey = parent.key;
        ancestors.push({ node, level: treeLevel });
      });
  });

  nodes.forEach((node) => {
    const parent = node.parentKey ? nodes.get(node.parentKey) : null;
    if (parent && !parent.children.includes(node.row)) parent.children.push(node.row);
  });

  const roots = Array.from(nodes.values())
    .filter((node) => !node.parentKey)
    .map((node) => node.key);

  return { nodes, roots };
}

function visitBranchChildren(
  index: TreeIndex,
  node: TreeNode,
  callback: (node: TreeNode, depth: number) => void,
  depth: number,
  path: Set<string>
) {
  if (path.has(node.key)) return;

  const nextPath = new Set(path);
  nextPath.add(node.key);
  callback(node, depth);

  node.children.forEach((childRow) => {
    const childNode = index.nodes.get(getTreeNodeKey(childRow, node.col));
    if (childNode) {
      visitBranchChildren(index, childNode, callback, depth + 1, nextPath);
    }
  });
}

export function createInitialCollapsedNodeKeys(index: TreeIndex) {
  const collapsedNodeKeys = new Set<string>();
  const visited = new Set<string>();

  index.roots.forEach((rootKey) => {
    const root = index.nodes.get(rootKey);
    if (!root) return;

    const showLevel = normalizeShowLevel(root.showLevel);
    // showLevel counts visible hierarchy levels, including the root at depth 1.
    visitBranchChildren(
      index,
      root,
      (node, depth) => {
        visited.add(node.key);
        if (depth >= showLevel) collapsedNodeKeys.add(node.key);
      },
      1,
      new Set()
    );
  });

  // Malformed or cyclic metadata must not recurse forever. Treat any
  // unreachable branch as a separate root and keep its local showLevel.
  index.nodes.forEach((node) => {
    if (visited.has(node.key)) return;
    const showLevel = normalizeShowLevel(node.showLevel);
    visitBranchChildren(
      index,
      node,
      (childNode, depth) => {
        visited.add(childNode.key);
        if (depth >= showLevel) collapsedNodeKeys.add(childNode.key);
      },
      1,
      new Set()
    );
  });

  return collapsedNodeKeys;
}

export function getHiddenRowsForCollapsedNodes(index: TreeIndex, collapsedNodeKeys: Set<string>) {
  const hiddenRows = new Set<number>();
  const visited = new Set<string>();

  function visit(node: TreeNode, hasCollapsedAncestor: boolean, path: Set<string>) {
    if (path.has(node.key)) return;

    visited.add(node.key);
    const nextPath = new Set(path);
    nextPath.add(node.key);
    const hideChildren = hasCollapsedAncestor || collapsedNodeKeys.has(node.key);

    node.children.forEach((childRow) => {
      if (hideChildren) hiddenRows.add(childRow);

      const childNode = index.nodes.get(getTreeNodeKey(childRow, node.col));
      if (childNode) visit(childNode, hideChildren, nextPath);
    });
  }

  index.roots.forEach((rootKey) => {
    const root = index.nodes.get(rootKey);
    if (root) visit(root, false, new Set());
  });

  index.nodes.forEach((node) => {
    if (!visited.has(node.key)) visit(node, false, new Set());
  });

  return hiddenRows;
}

function getValidRows(hot: Core, rows: Iterable<number>) {
  const rowCount = hot.countRows();
  return Array.from(rows).filter((row) => Number.isInteger(row) && row >= 0 && row < rowCount);
}

function applyTreeHiddenRows(hot: Core, previousRows: Set<number>, targetRows: Set<number>, force = false) {
  const hiddenRowsPlugin = hot.getPlugin('hiddenRows');
  const rowsToShow = getValidRows(
    hot,
    force ? previousRows : Array.from(previousRows).filter((row) => !targetRows.has(row))
  );
  const rowsToHide = getValidRows(
    hot,
    force ? targetRows : Array.from(targetRows).filter((row) => !previousRows.has(row))
  );

  if (rowsToShow.length) hiddenRowsPlugin.showRows(rowsToShow);
  if (rowsToHide.length) hiddenRowsPlugin.hideRows(rowsToHide);
}

function syncTreeCellMeta(hot: Core, index: TreeIndex, collapsedNodeKeys: Set<string>) {
  index.nodes.forEach((node) => {
    hot.setCellMeta(node.row, node.col, 'children', node.children);
    hot.setCellMeta(node.row, node.col, 'expanded', !collapsedNodeKeys.has(node.key));
  });
}

export function initializeTreeRows(hot: Core, treeRows: TreeRowMeta[] = [], cells: TreeRowMeta[] = []) {
  const previousState = treeStateByHot.get(hot);
  const index = buildTreeIndex(mergeTreeRows(treeRows, cells));
  const collapsedNodeKeys = createInitialCollapsedNodeKeys(index);
  const hiddenRows = getHiddenRowsForCollapsedNodes(index, collapsedNodeKeys);

  // loadData() can reset Handsontable's index maps. Reapply the complete target
  // state instead of relying only on the difference from the previous sheet.
  applyTreeHiddenRows(hot, previousState?.hiddenRows ?? new Set(), hiddenRows, true);
  syncTreeCellMeta(hot, index, collapsedNodeKeys);
  treeStateByHot.set(hot, { index, collapsedNodeKeys, hiddenRows });

  // The preview loader suspends rendering before it applies cells. Requesting a
  // full render here makes resumeRender() rerun the first viewport after the
  // tree meta is ready, instead of reusing the row-0 render created by the
  // earlier settings update.
  hot.render();
}

export function toggleTreeNode(hot: Core, row: number, col: number) {
  const state = treeStateByHot.get(hot);
  const key = getTreeNodeKey(row, col);
  const node = state?.index.nodes.get(key);
  if (!state || !node?.children.length) return false;

  if (state.collapsedNodeKeys.has(key)) {
    state.collapsedNodeKeys.delete(key);
  } else {
    state.collapsedNodeKeys.add(key);
  }

  const hiddenRows = getHiddenRowsForCollapsedNodes(state.index, state.collapsedNodeKeys);
  applyTreeHiddenRows(hot, state.hiddenRows, hiddenRows);
  syncTreeCellMeta(hot, state.index, state.collapsedNodeKeys);
  state.hiddenRows = hiddenRows;
  hot.render();
  return true;
}

