import { stripNoOpBgFillFromClassName } from '@/components/report/design/utils/classname';
import { registerTableCellRootCleanup } from '@/components/report/preview/plugins/cellRootLifecycle';
import { defaultClassName } from '@/constants/cellMetas';
import { HotTableClass } from '@handsontable/react';
import { NG } from '@newgrand/udp-ui';
import CSSType from '../../../../constants/CSSType';
import { toogleFrozenBorder } from '../../design/components/customTable/utils/frozen';
import { initializeTreeRows } from '../plugins/treeRender/utils';
import { defaultColWidths, defaultRowHeights } from '../table/settings';
import { getIsMobile } from '../utils/isMobile';
import { createVirtualizedMergeCellsSettings, IMergeCell } from './mergeVirtualization';
import { syncPreviewStyleRules } from './styleSheetRegistry';

const isReport = () =>
  NG.getHistory().location.pathname === '/tableDesign/TableManager/preview' ||
  NG.getHistory().location.pathname === '/tableDesign/PrintManager/preview';

const defaultRowCount = 20;
const defaultColCount = 10;

function normalizeSpan(value: unknown) {
  const span = Number(value);
  return Number.isFinite(span) && span > 0 ? span : 1;
}

function normalizeMergeCell(item: Partial<IMergeCell>): IMergeCell | null {
  const row = Number(item?.row);
  const col = Number(item?.col);
  if (!Number.isFinite(row) || !Number.isFinite(col)) return null;

  return {
    row,
    col,
    rowspan: normalizeSpan(item?.rowspan),
    colspan: normalizeSpan(item?.colspan)
  };
}

function buildMergeCellsFromCells(cells: any[] = []) {
  return (Array.isArray(cells) ? cells : []).reduce<IMergeCell[]>((acc, cell) => {
    const mergeCell = normalizeMergeCell(cell);
    if (mergeCell && (mergeCell.rowspan > 1 || mergeCell.colspan > 1)) {
      acc.push(mergeCell);
    }
    return acc;
  }, []);
}

function getMergeCells(cells: any[] = [], globalSettings: any = {}) {
  const globalMergeCells = Array.isArray(globalSettings?.mergeCells) ? globalSettings.mergeCells : [];
  const source = globalMergeCells.length ? globalMergeCells : buildMergeCellsFromCells(cells);
  const mergeCellMap = new Map<string, IMergeCell>();
  source.forEach((item) => {
    const mergeCell = normalizeMergeCell(item);
    if (!mergeCell || (mergeCell.rowspan <= 1 && mergeCell.colspan <= 1)) return;
    mergeCellMap.set(`${mergeCell.row}-${mergeCell.col}`, mergeCell);
  });
  return Array.from(mergeCellMap.values());
}

function isCoveredByMergeCell(target: IMergeCell, mergeCells: IMergeCell[]) {
  return mergeCells.some((mergeCell) => {
    if (mergeCell.row === target.row && mergeCell.col === target.col) return false;
    const inRow = target.row >= mergeCell.row && target.row < mergeCell.row + mergeCell.rowspan;
    const inCol = target.col >= mergeCell.col && target.col < mergeCell.col + mergeCell.colspan;
    return inRow && inCol;
  });
}

function filterCoveredMergeCells(mergeCells: IMergeCell[]) {
  return mergeCells.filter((mergeCell) => !isCoveredByMergeCell(mergeCell, mergeCells));
}

function isCoveredCell(row: number, col: number, mergeCells: IMergeCell[]) {
  return mergeCells.some((mergeCell) => {
    if (mergeCell.row === row && mergeCell.col === col) return false;
    const inRow = row >= mergeCell.row && row < mergeCell.row + mergeCell.rowspan;
    const inCol = col >= mergeCell.col && col < mergeCell.col + mergeCell.colspan;
    return inRow && inCol;
  });
}

function getCellsBounds(cells: any[] = []) {
  return (Array.isArray(cells) ? cells : []).reduce(
    (bounds, cell) => {
      const row = Number(cell?.row);
      const col = Number(cell?.col);
      if (!Number.isFinite(row) || !Number.isFinite(col)) return bounds;

      bounds.rowCount = Math.max(bounds.rowCount, row + normalizeSpan(cell?.rowspan));
      bounds.colCount = Math.max(bounds.colCount, col + normalizeSpan(cell?.colspan));
      return bounds;
    },
    { rowCount: 0, colCount: 0 }
  );
}

function normalizeCount(value: unknown, fallback: number) {
  const count = Number(value);
  return Number.isFinite(count) && count > 0 ? count : fallback;
}

/**
 * 应用斑马色：根据 zebraStriped 和 stripeColor 设置交替行背景
 */
function applyZebraStripes(
  hotInstance: any,
  globalSettings: { zebraStriped?: number | boolean; stripeColor?: string }
) {
  const rootEl = hotInstance?.rootElement;
  if (!rootEl) return;

  const zebraStriped = globalSettings?.zebraStriped;
  const stripeColor = globalSettings?.stripeColor;
  const isZebraEnabled = zebraStriped === 1 || zebraStriped === true;
  let color = '#f5f5f5';
  if (stripeColor) {
    color = stripeColor.startsWith('#') ? stripeColor : `#${stripeColor}`;
  }

  if (isZebraEnabled && color) {
    rootEl.classList.add('htZebraStriped');
    rootEl.style.setProperty('--ht-stripe-color', color);
  } else {
    rootEl.classList.remove('htZebraStriped');
    rootEl.style.removeProperty('--ht-stripe-color');
  }
}

export function handleLoadGlobalSettings(hot: HotTableClass, cells, globalSettings) {
  const mergeCells = filterCoveredMergeCells(getMergeCells(cells, globalSettings));
  const normalizedCells =
    cells
      ?.filter((c) => {
        const row = Number(c?.row);
        const col = Number(c?.col);
        if (!Number.isFinite(row) || !Number.isFinite(col)) return true;
        return !isCoveredCell(row, col, mergeCells);
      })
      .map((c) => {
        if (!c) return c;
        const { rowspan, colspan, hidden, mergeParent, ...cell } = c;
        if (!cell?.className) return cell;
        const next = stripNoOpBgFillFromClassName(cell.className);
        const className = next.trim() ? next : defaultClassName;
        return { ...cell, className };
      }) ?? cells;

  const aggregateClass = stripNoOpBgFillFromClassName(globalSettings?.className ?? '');
  const usedClassName: Set<string> = new Set(aggregateClass.split(' ').filter(Boolean));

  const { hotInstance } = hot;
  if (hotInstance) {
    registerTableCellRootCleanup(hotInstance);
    syncPreviewStyleRules(hotInstance, buildPreviewStyleRules(usedClassName));
  }

  const cellsBounds = getCellsBounds(cells);
  let rowCount = normalizeCount(globalSettings?.rowCount ?? globalSettings?.rows, defaultRowCount);
  let colCount = normalizeCount(globalSettings?.colCount ?? globalSettings?.cols, defaultColCount);
  rowCount = Math.max(rowCount, cellsBounds.rowCount || defaultRowCount);
  colCount = Math.max(colCount, cellsBounds.colCount || defaultColCount);

  mergeCells.forEach((item) => {
    colCount = Math.max(colCount, item.col + item.colspan);
    rowCount = Math.max(rowCount, item.row + item.rowspan);
  });

  const manualColumnWidths: any[] = [];
  const manualRowHeights: any[] = [];

  if (globalSettings?.widths && globalSettings?.widths.length > 0) {
    globalSettings?.widths.forEach(({ width, col }) => {
      manualColumnWidths[col] = width;
    });
  }

  if (globalSettings?.heights && globalSettings?.heights.length > 0) {
    globalSettings?.heights.forEach(({ height, row }) => {
      manualRowHeights[row] = height;
    });
  }

  hotInstance?.suspendRender();

  // 先设置列宽和行高
  const colWidthsArr = Array.from({ length: colCount }, (_, i) => manualColumnWidths[i] || defaultColWidths);
  const rowHeightsArr = Array.from({ length: rowCount }, (_, i) => manualRowHeights[i] || defaultRowHeights);

  hotInstance?.updateSettings({
    colWidths: colWidthsArr,
    rowHeights: rowHeightsArr,

    minRows: rowCount,
    minCols: colCount,
    mergeCells: createVirtualizedMergeCellsSettings()
  });

  // 更新sheet数据：loadData + updateSettings
  hotInstance?.loadData([[]]);

  // 更新单元格
  hotInstance?.updateSettings({
    cell: normalizedCells
  });

  // Keep logical merges intact while preventing them from expanding the rendered viewport.
  hotInstance?.updateSettings({
    mergeCells: createVirtualizedMergeCellsSettings(mergeCells)
  });

  // Initialize tree visibility from the configured default display level.
  if (hotInstance) {
    initializeTreeRows(hotInstance, globalSettings?.treeRows ?? [], normalizedCells ?? []);
  }

  hotInstance?.resumeRender();

  // 再更新冻结
  const frozen = globalSettings?.frozen || {
    rowStart: 0,
    colStart: 0
  };

  // 报表模式下才需要设置冻结
  !getIsMobile() &&
    isReport() &&
    hotInstance?.updateSettings({
      fixedRowsTop: frozen.rowStart,
      fixedColumnsStart: frozen.colStart
    });

  toogleFrozenBorder(frozen.rowStart, frozen.colStart);

  // 设置背景图片
  if (globalSettings?.bgShowType === 0) {
    // 获取所有的table dom节点
    const tables: NodeListOf<HTMLTableElement> = document.querySelectorAll('.htCore');
    tables.forEach((table) => {
      table.style.backgroundImage = globalSettings?.bg ? `url(${globalSettings.bg})` : 'none';
      table.style.backgroundColor = globalSettings?.bg ? 'transparent' : '#fff';
    });
  }

  // 斑马色：根据 zebraStriped 和 stripeColor 应用交替行背景色
  applyZebraStripes(hotInstance, globalSettings);

  // if (!getIsMobile()) {
  //   const timer = setTimeout(() => {
  //     hotInstance?.updateSettings({
  //       rowHeaders: true,
  //       colHeaders: true
  //     });
  //     clearTimeout(timer);
  //   }, 1000);
  // }

  NG.getPageInstance().umiDispatch({
    type: 'updateHotLoading',
    payload: false
  });
}

/**
 *预加载
  eg: htBorder_Top_1_000
  eg: htBgFill_000
 */
function buildPreviewStyleRules(usedClassName: Set<string>) {
  const rules: string[] = [];
  usedClassName.forEach((classname) => {
    if (!classname) return;
    const [key, value, ...rest] = classname.split('_');

    switch (key) {
      case CSSType.BgFill:
        if (value === 'transparent' || String(value).toLowerCase() === 'ffffff00') {
          break;
        }
        rules.push(createCSSRule(key, `#${value}`));
        break;
      case CSSType.FontColor:
        rules.push(createCSSRule(key, '#' + value));
        break;
      case CSSType.border:
        // eslint-disable-next-line no-case-declarations
        const [width, color] = rest;
        rules.push(
          createCSSRule(key, {
            direction: value.toLowerCase(),
            classname,
            width,
            color
          })
        );
        break;
      default:
        rules.push(createCSSRule(key, value));
        break;
    }
  });
  return rules.filter(Boolean);
}

function createCSSRule(type, value) {
  const map = {
    [CSSType.BgFill]: (color) => `.handsontable td.${generateClassName(type, value)} { background-color: ${color}; }`,

    [CSSType.border]: (border) =>
      `.handsontable td.${border.classname} {
          border-${border.direction}: ${border.width}px solid #${border.color} !important;
      }`,

    [CSSType.FontColor]: (color) => `.handsontable td.${generateClassName(type, value)} { color: ${color}; }`,
    [CSSType.FontSize]: (size) => `.handsontable td.${generateClassName(type, value)} { font-size: ${size}px; }`,
    [CSSType.FontWeight]: (weight) => `.handsontable td.${generateClassName(type, value)} { font-weight: ${weight}; }`,
    [CSSType.FontItalic]: (italic) => `.handsontable td.${generateClassName(type, value)} { font-style: ${italic}; }`,
    [CSSType.FontFamily]: (family) => `.handsontable td.${generateClassName(type, value)} { font-family: ${family}; }`,
    [CSSType.FontUnderline]: (underline) =>
      `.handsontable td.${generateClassName(type, value)} { text-decoration: ${underline}; }`
  };

  return map[type]?.(value) ?? '';
}

// 生成classname
export function generateClassName(type, value) {
  value = (value || '').split(' ')?.join('_');
  if (value.indexOf('#') === -1) {
    return `${type}_${value}`;
  }
  return `${type}_${value.replace('#', '')}`;
}

