  }
];

const restored = applySchemaTreeShowLevels(response, { schema });
assert.notEqual(restored, response, 'the API response must not be mutated');
assert.equal(response[0].cells[0].showLevel, undefined);
assert.deepEqual(
  restored[0].cells.map((cell) => cell.showLevel),
  [2, 2, 2, 2]
);

const hiddenRows = new Set<number>();
const hot = {
  countRows: () => 4,
  getPlugin: () => ({
    showRows: (rows: number[]) => rows.forEach((row) => hiddenRows.delete(row)),
    hideRows: (rows: number[]) => rows.forEach((row) => hiddenRows.add(row))
  }),
  setCellMeta: () => undefined,
  render: () => undefined
};

initializeTreeRows(hot as any, restored[0].globalSettings.treeRows, restored[0].cells as any);
assert.deepEqual(Array.from(hiddenRows), [2, 3], 'showLevel 2 must hide descendants deeper than level 2');

const explicitResponse = clone(response);
explicitResponse[0].cells[0].showLevel = 0;
const explicitRestored = applySchemaTreeShowLevels(explicitResponse, { schema });
assert.equal(
  explicitRestored[0].cells[0].showLevel,
  0,
  'an explicit API level must take precedence over schema fallback'
);

const legacyZeroRows = new Set<number>();
const legacyZeroHot = {
  ...hot,
  getPlugin: () => ({
    showRows: (rows: number[]) => rows.forEach((row) => legacyZeroRows.delete(row)),
    hideRows: (rows: number[]) => rows.forEach((row) => legacyZeroRows.add(row))
  })
};
initializeTreeRows(legacyZeroHot as any, [], explicitRestored[0].cells as any);
assert.deepEqual(Array.from(legacyZeroRows), [1, 2, 3], 'legacy showLevel 0 must be treated as level 1');

const ambiguousSchema = JSON.stringify([
  {
    sheetKey: '0',
    cells: [
      { row: 0, col: 0, cellType: 'tree', cellData: { treeConfig: { showLevel: 1 } } },
      { row: 5, col: 0, cellType: 'tree', cellData: { treeConfig: { showLevel: 2 } } }
    ]
  }
]);
assert.equal(
  applySchemaTreeShowLevels(response, { schema: ambiguousSchema })[0].cells[0].showLevel,
  undefined,
  'different levels in one output column must not be guessed'
);

assert.equal(applySchemaTreeShowLevels(response, { schema: 'invalid' }), response);

console.log('tree preview schema level tests passed');

function clone<T>(value: T): T {
  return JSON.parse(JSON.stringify(value));
}

