// --- 新增水平筛选逻辑 ---

// 结合多筛选条件（水平方向）
function getDataWithMutipledCondition_Col(isReset, filterInfo: FilterInfo, range: FilterRange, newCells: CellMeta[][]) {
  const filterInfoMap = updateFilterRangeMap(isReset ? 'reset' : 'update', range, filterInfo, newCells);

  const currentInfoMap = filterInfoMap[range.key];
  const showCols: number[] = [];
  const hiddenCols: number[] = [];

  const { indexSort, indexMap } = currentInfoMap;
  // 如果全部重置，返回原数据 (显示所有列)
  if (indexSort.length === 0) {
    return { showCols, hiddenCols, filterInfoMap };
  }

  // 最终的列
  let resCheckedColIndex: number[] = [];
  // 多条件时 (多个行进行筛选)
  if (indexSort.length > 1) {
    // 调用实际实现的函数
    resCheckedColIndex = getColIndexByMutipleFilter(currentInfoMap, newCells);
  } else {
    // 第一次筛选 (单个行进行筛选)
    const p_filterInfo = indexMap[indexSort[indexSort.length - 1]];
    // 调用实际实现的函数
    resCheckedColIndex = getAllCheckedColGroup(p_filterInfo).flat();
  }

  // --- 根据 resCheckedColIndex 计算 showCols 和 hiddenCols ---
  const checkedColSet = new Set(resCheckedColIndex);

  for (let i = range.from; i <= range.to; i++) {
    if (checkedColSet.has(i)) {
      showCols.push(i);
    } else {
      hiddenCols.push(i);
    }
  }
  return { showCols, hiddenCols, filterInfoMap };
}

// 渲染水平方向的筛选，未作排序
function renderCol(props: RenderProps) {
  const { hot, range, isReset, filterInfo } = props;
  const { sheets, defaultSheet, userLayouts, newCells } = NG.getPageInstance().getDvaState();

  // !! 注意: getDataWithMutipledCondition_Col 依赖未实现的辅助函数
  const updateData = getDataWithMutipledCondition_Col(isReset, filterInfo, range, newCells[defaultSheet]);
  const { showCols, hiddenCols, filterInfoMap } = updateData;

  // 更新布局和全局设置 (这部分可能不需要针对列筛选做特殊处理，待确认)
  const lastestGlobalSettings = {
    ...sheets[defaultSheet].globalSettings,
    ...(userLayouts.find((item) => item.sheetKey === String(defaultSheet))?.layoutConfig ?? {})
  };
  // handleLoadGlobalSettings 可能需要检查是否影响列隐藏
  handleLoadGlobalSettings({ hotInstance: hot } as any, newCells[defaultSheet].flat(), lastestGlobalSettings);

  const hiddenColumnsPlugin = hot.getPlugin('hiddenColumns');

  // 后置显示隐藏行
  hiddenColumnsPlugin.showColumns(showCols);
  hiddenColumnsPlugin.hideColumns(hiddenCols);

  // 渲染
  hot.render();
}

